var n=`1224-carimanolas`;var a=`world-1224`;var o=`PA`;var t=`central-america-caribbean`;var s=8;var r=79;var l={en:`Carimañolas`,ua:`Каріманьйолас`};var d={en:`Carimañolas is a dish from Panama featuring cassava root, ground beef, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Каріманьйолас, страва кухні країни Панама з такими основними складниками: маніок, яловичий фарш, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Cook the listed ingredients in simmering water for about 27 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 27 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:27,i:[[`cassava-root`,1050,`g`],[`water`,1200,`ml`],[`table-salt`,8,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 10 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 10 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:10,i:[[`unsalted-butter`,40,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:13,i:[[`ground-beef`,420,`g`],[`yellow-onion`,130,`g`],[`garlic`,4,`clove`],[`tomato-paste`,35,`g`]]},{en:`Enclose the cooled cooked beef in mashed cassava, shaping smooth sealed cylinders before deep frying.`,ua:`Загорніть охолоджену готову яловичу начинку в пюре з маніоку, сформувавши гладкі герметичні циліндри перед смаженням у фритюрі.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,850,`ml`]]}];var m={slug:n,id:a,country:`PA`,region:t,servings:8,minutes:79,title:l,text:d,steps:g};export{o as country,m as default,a as id,r as minutes,t as region,s as servings,n as slug,g as steps,d as text,l as title};